    # First check environment (handy when Railway CLI is unavailable)
    env_token = os.environ.get("telegram_bot_token", "") or os.environ.get(
        "TRA_TELEGRAM_BOT_TOKEN", ""
    )
    if env_token:
        return env_token.strip()

    # Fall back to Railway CLI
    out = run(
        [
            "railway",
            "variables",
            "list",
            "--service",
            "new-trade",
            "--environment",
            "production",
            "--json",
        ]
    )
    if not out:
        return ""
    try:
        data = json.loads(out)
        for item in data:
            if item.get("name") == "telegram_bot_token":
                return item.get("value", "")
    except Exception:
        pass
    return """}

{"content": "@echo off
REM Monitor runner for Windows Task Scheduler
REM Runs every 5 minutes, silently checks for events.
REM Outputs nothing if there's nothing to report.

cd /d "D:\projects\new trade"

REM Read key env vars from .env (only the ones we need)
for /f "usebackq tokens=1* delims==" %%a in (".env") do (
    if /i "%%a"=="TRA_TELEGRAM_BOT_TOKEN" set telegram_bot_token=%%b
    if /i "%%a"=="TRA_TELEGRAM_CHAT_ID" set TRA_TELEGRAM_CHAT_ID=%%b
)

set MONITOR_API_URL=http://localhost:8081/api/paper-report
set MONITOR_CHAT_ID=%TRA_TELEGRAM_CHAT_ID%
set telegram_bot_token=%telegram_bot_token%

REM Use the project's .venv Python if available, else system Python
if exist .venv\Scripts\python.exe (
    .venv\Scripts\python.exe scripts/monitor.py
) else (
    C:\Python314\python.exe scripts/monitor.py
)
", "path": "D:/projects/new trade/scripts/run_monitor.cmd"}

