209|#[pymethods]
210|impl Instrument {
211|    #[new]
212|    pub fn new(
213|        instrument_id: InstrumentId,
214|        tick_size: &str,
215|        step_size: u64,
216|        multiplier: &str,
217|        contract_type: ContractType,
218|        currency: &str,
219|        precision: u32,
220|    ) -> PyResult<Self> {
221|        let ts = Decimal::from_str(tick_size)
222|            .map_err(|e| PyValueError::new_err(format!("Invalid tick_size '{}': {}", tick_size, e)))?;
223|        let mult = Decimal::from_str(multiplier)
224|            .map_err(|e| PyValueError::new_err(format!("Invalid multiplier '{}': {}", multiplier, e)))?;
225|        if ts <= Decimal::ZERO {
226|            return Err(PyValueError::new_err("tick_size must be positive"));
227|        }
228|        if step_size == 0 {
229|            return Err(PyValueError::new_err("step_size must be positive"));
230|        }
231|        if mult <= Decimal::ZERO {
232|            return Err(PyValueError::new_err("multiplier must be positive"));
233|        }
234|        Ok(Self {
235|            instrument_id,
236|            tick_size: ts,
237|            step_size,
238|            multiplier: mult,
239|            contract_type,
240|            currency: currency.to_string(),
241|            precision,
242|        })
243|    }
