251|    /// Check that a price is aligned to the instrument's tick size.
252|    pub fn is_price_aligned(&self, price: &str) -> bool {
253|        let p = match Decimal::from_str(price) {
254|            Ok(v) => v,
255|            Err(_) => return false,
256|        };
257|        p % self.tick_size == Decimal::ZERO
258|    }
259|
260|    /// Check that a quantity is aligned to the instrument's step size (lot size).
261|    pub fn is_quantity_aligned(&self, quantity: u64) -> bool {
262|        quantity % self.step_size == 0
263|    }
264|
265|    /// Compute the notional value of an order: quantity * price * multiplier.
266|    pub fn compute_notional(&self, quantity: u64, price: &str) -> PyResult<String> {
267|        let p = Decimal::from_str(price)
268|            .map_err(|e| PyValueError::new_err(format!("Invalid price '{}': {}", price, e)))?;
269|        let q = Decimal::from(quantity);
270|        let notional = q * p * self.multiplier;
271|        Ok(notional.to_string())
272|    }
273|
274|    /// Validate an order against instrument metadata. Returns an error message string
275|    /// on failure, or None on success.
276|    pub fn validate_order(&self, side: &str, quantity: u64, price: &str) -> Option<String> {
277|        let side_upper = side.to_uppercase();
278|        if side_upper != "BUY" && side_upper != "SELL" {
279|            return Some(format!("Invalid side '{}'", side));
280|        }
281|        if !self.is_quantity_aligned(quantity) {
282|            return Some(format!(
283|                "Quantity {} is not aligned to step size {}",
284|                quantity, self.step_size
285|            ));
286|        }
287|        if !self.is_price_aligned(price) {
288|            return Some(format!(
289|                "Price {} is not aligned to tick size {}",
290|                price, self.tick_size
291|            ));
292|        }
293|        None
294|    }
295|
296|    fn __str__(&self) -> String {
297|        format!("{} ({:?})", self.instrument_id, self.contract_type)
298|    }
299|
300|    fn __repr__(&self) -> String {
301|        format!(
302|            "Instrument({}, tick={}, step={}, mult={}, type={:?}, cur={}, prec={})",
303|            self.instrument_id, self.tick_size, self.step_size, self.multiplier,
304|            self.contract_type, self.currency, self.precision
305|        )
306|    }
