214|#[cfg(test)]
215|mod tests {
216|    use super::*;
217|
218|    #[test]
219|    fn test_normal_lifecycle() {
220|        let mut m = StateMachineCore::new();
221|        assert_eq!(m.current, OrderState::New);
222|
223|        m.transition(OrderState::Validated).unwrap();
224|        assert_eq!(m.current, OrderState::Validated);
225|
226|        m.transition(OrderState::Submitted).unwrap();
227|        assert_eq!(m.current, OrderState::Submitted);
228|
229|        m.transition(OrderState::Acknowledged).unwrap();
