236|        assert_eq!(m.current, OrderState::Filled);
237|    }
238|
239|    #[test]
240|    fn test_direct_acknowledged_to_filled() {
241|        let mut m = StateMachineCore::new();
242|        m.transition(OrderState::Validated).unwrap();
243|        m.transition(OrderState::Submitted).unwrap();
244|        m.transition(OrderState::Acknowledged).unwrap();
245|        m.transition(OrderState::Filled).unwrap();
246|        assert_eq!(m.current, OrderState::Filled);
247|    }
248|
249|
250|    #[test]
251|    fn test_rejection_from_new() {
252|        let mut m = StateMachineCore::new();
253|        m.transition(OrderState::Rejected).unwrap();
254|        assert_eq!(m.current, OrderState::Rejected);
255|        assert!(m.current.is_terminal());
