272|        let mut m = StateMachineCore::new();
273|        m.transition(OrderState::Validated).unwrap();
274|        m.transition(OrderState::Submitted).unwrap();
275|        m.transition(OrderState::Unknown).unwrap();
276|        assert_eq!(m.current, OrderState::Unknown);
277|
278|        m.transition(OrderState::Acknowledged).unwrap();
279|        assert_eq!(m.current, OrderState::Acknowledged);
280|    }
281|
