283|    fn test_terminal_state_rejects_transitions() {
284|        let mut m = StateMachineCore::new();
285|        // Can't go directly to Filled; use the full lifecycle
286|        m.transition(OrderState::Validated).unwrap();
287|        m.transition(OrderState::Submitted).unwrap();
288|        m.transition(OrderState::Acknowledged).unwrap();
289|        m.transition(OrderState::PartiallyFilled).unwrap();
