286|                accepted: false,
287|                reason: Some(RiskReasonCode::KillSwitchTriggered),
288|                reason_detail: "Kill switch is blocking routing".to_string(),
289|            };
290|        }
291|
292|        // b. Trading state check
293|        if !self.trading_state.accepts_intents() {
294|            return RiskVerdict {
295|                accepted: false,
296|                reason: Some(RiskReasonCode::TradingHalted),
297|                reason_detail: "Trading is not accepting intents".to_string(),
298|            };
299|        }
300|
301|        // c. Data freshness / clock drift check
302|        let threshold_ms = self.config.data_freshness_threshold_ms as i64
303|            + self.config.clock_skew_tolerance_ms as i64;
304|        if let Ok(market_ts) = intent.market_data_timestamp.parse::<DateTime<Utc>>() {
305|            let drift = (Utc::now() - market_ts).num_milliseconds().abs();
306|            if drift > threshold_ms {
307|                return RiskVerdict {
308|                    accepted: false,
309|                    reason: Some(RiskReasonCode::DataStale),
310|                    reason_detail: format!(
311|                        "Market data timestamp {} is {}ms from system clock (threshold: {}ms)",
312|                        intent.market_data_timestamp, drift, threshold_ms,
313|                    ),
314|                };
315|            }
316|        } else {
317|            return RiskVerdict {
318|                accepted: false,
319|                reason: Some(RiskReasonCode::DataStale),
320|                reason_detail: format!(
321|                    "Market data timestamp '{}' is not a valid RFC 3339 timestamp",
322|                    intent.market_data_timestamp,
323|                ),
324|            };
325|        }
326|
327|        // d. Instrument eligibility
328|        if !self.config.instrument_eligibility.is_empty()
329|            && !self.config.instrument_eligibility.contains(&intent.instrument_id)
330|        {
331|            return RiskVerdict {
332|                accepted: false,
333|                reason: Some(RiskReasonCode::InstrumentNotEligible),
334|                reason_detail: format!("Instrument {} is not eligible", intent.instrument_id),
335|            };
336|        }
337|
338|        // e. Order limits — notional
339|        let qty = match (
340|            Decimal::from_str(&intent.quantity),
341|            intent.price.as_ref().map(|p| Decimal::from_str(p)).transpose(),
342|        ) {
343|            (Ok(q), Ok(Some(p))) => {
344|                let notional = q * p;
345|                if notional > self.config.max_order_notional.amount {
346|                    return RiskVerdict {
347|                        accepted: false,
348|                        reason: Some(RiskReasonCode::OrderNotionalExceeded),
349|                        reason_detail: format!("Order notional {} exceeds max {}", notional, self.config.max_order_notional.amount),
350|                    };
351|                }
352|                q
353|            }
354|            (Ok(q), Ok(None)) => q,
355|            _ => {
356|                return RiskVerdict {
357|                    accepted: false,
358|                    reason: Some(RiskReasonCode::InternalError),
359|                    reason_detail: "Invalid decimal in intent quantity or price".to_string(),
360|                };
361|            }
362|        };
363|
364|        // f. Order limits — quantity
365|        if qty > Decimal::from(self.config.max_order_quantity) {
366|            return RiskVerdict {
367|                accepted: false,
368|                reason: Some(RiskReasonCode::OrderQuantityExceeded),
369|                reason_detail: format!("Order quantity {} exceeds max {}", qty, self.config.max_order_quantity),
370|            };
371|        }
372|
373|        // g. Position/exposure limits
374|        if let Some(pos) = current_position_size
375|            && pos > self.config.max_position_size
376|        {
377|            return RiskVerdict {
378|                accepted: false,
379|                reason: Some(RiskReasonCode::PositionLimitExceeded),
380|                reason_detail: format!("Position size {} exceeds max {}", pos, self.config.max_position_size),
381|            };
382|        }
383|
384|        // h. Gross exposure check
385|        if let Some(exp) = current_gross_exposure
386|            && exp.amount > self.config.max_gross_exposure.amount
387|        {
388|            return RiskVerdict {
389|                accepted: false,
390|                reason: Some(RiskReasonCode::GrossExposureExceeded),
391|                reason_detail: format!("Gross exposure {} exceeds max {}", exp.amount, self.config.max_gross_exposure.amount),
392|            };
393|        }
394|
395|        // i. Drawdown check
396|        if let Some(dd) = current_drawdown
397|            && dd > self.config.max_drawdown_fraction
398|        {
399|            return RiskVerdict {
400|                accepted: false,
401|                reason: Some(RiskReasonCode::DrawdownExceeded),
402|                reason_detail: format!("Drawdown {} exceeds max {}", dd, self.config.max_drawdown_fraction),
403|            };
404|        }
405|
406|        // j. Daily loss check
407|        if let Some(dl) = current_daily_loss
408|            && dl.amount.abs() > self.config.max_daily_loss.amount
409|        {
410|            return RiskVerdict {
411|                accepted: false,
412|                reason: Some(RiskReasonCode::DailyLossExceeded),
413|                reason_detail: format!("Daily loss {} exceeds max {}", dl.amount, self.config.max_daily_loss.amount),
414|            };
415|        }
416|
417|        // k. Side validation — don't trade more than we hold
418|        if let (Some(side), Some(qty)) = (&current_position_side, current_position_size) {
419|            let side_upper = side.to_uppercase();
420|            let intent_qty = Decimal::from_str(&intent.quantity).unwrap_or(Decimal::ZERO);
421|            if intent.side == "SELL" && side_upper == "LONG" && intent_qty > Decimal::from(qty) {
422|                return RiskVerdict {
423|                    accepted: false,
424|                    reason: Some(RiskReasonCode::SellExceedsPosition),
425|                    reason_detail: format!(
426|                        "Sell {} exceeds long position of {}",
427|                        intent_qty, qty
428|                    ),
429|                };
430|            }
431|            if intent.side == "BUY" && side_upper == "SHORT" && intent_qty > Decimal::from(qty) {
432|                return RiskVerdict {
433|                    accepted: false,
434|                    reason: Some(RiskReasonCode::BuyExceedsShortPosition),
435|                    reason_detail: format!(
436|                        "Buy-to-cover {} exceeds short position of {}",
437|                        intent_qty, qty
438|                    ),
439|                };
440|            }
441|        }
442|
443|        // l. Correlation check
444|        if let Some(scores) = &correlation_scores {
445|            if !scores.is_empty() {
446|                let mean: f64 = scores.iter().sum::<f64>() / scores.len() as f64;
447|                if mean > self.config.max_correlated_exposure {
448|                    return RiskVerdict {
449|                        accepted: false,
450|                        reason: Some(RiskReasonCode::CorrelatedExposureExceeded),
451|                        reason_detail: format!(
452|                            "Mean correlation {:.4} exceeds max {:.2}",
453|                            mean, self.config.max_correlated_exposure,
454|                        ),
455|                    };
456|                }
457|            }
458|        }
459|
460|        RiskVerdict {
461|            accepted: true,
462|            reason: None,
463|            reason_detail: String::new(),
464|        }
465|    }
