8|// ─── ReconciliationDriftSeverity ────────────────────────────────────────────────
9|
10|#[pyclass(eq, eq_int)]
11|#[derive(Clone, Debug, PartialEq)]
12|pub enum ReconciliationDriftSeverity {
13|    InSync,
14|    Warning,
15|    Critical,
16|}
17|
18|// ─── PositionDrift ──────────────────────────────────────────────────────────────
19|
20|#[pyclass]
21|#[derive(Clone, Debug)]
22|pub struct PositionDrift {
23|    #[pyo3(get)]
24|    pub instrument_id: String,
25|    #[pyo3(get)]
26|    pub expected_side: String,
27|    #[pyo3(get)]
28|    pub expected_quantity: i64,
29|    #[pyo3(get)]
30|    pub actual_side: String,
31|    #[pyo3(get)]
32|    pub actual_quantity: i64,
33|    #[pyo3(get)]
34|    pub quantity_drift: i64,
35|}
36|
37|// ─── ReconciliationResult ────────────────────────────────────────────────────────
38|
39|#[pyclass]
40|#[derive(Clone, Debug)]
41|pub struct ReconciliationResult {
42|    #[pyo3(get)]
43|    pub severity: ReconciliationDriftSeverity,
44|    #[pyo3(get)]
45|    pub position_drifts: Vec<PositionDrift>,
46|    #[pyo3(get)]
47|    pub cash_expected: Money,
48|    #[pyo3(get)]
49|    pub cash_actual: Money,
50|    #[pyo3(get)]
51|    pub cash_drift: Money,
52|    #[pyo3(get)]
53|    pub summary: String,
54|}
