56|// ─── ReconciliationConfig ────────────────────────────────────────────────────────
57|
58|#[pyclass]
59|#[derive(Clone, Debug)]
60|pub struct ReconciliationConfig {
61|    #[pyo3(get, set)]
62|    pub critical_drift_fraction: f64,
63|    #[pyo3(get, set)]
64|    pub warning_drift_fraction: f64,
65|}
66|
67|#[pymethods]
68|impl ReconciliationConfig {
69|    #[new]
70|    #[pyo3(signature = (critical_drift_fraction=None, warning_drift_fraction=None))]
71|    pub fn new(critical_drift_fraction: Option<f64>, warning_drift_fraction: Option<f64>) -> Self {
72|        Self {
73|            critical_drift_fraction: critical_drift_fraction.unwrap_or(0.05),
74|            warning_drift_fraction: warning_drift_fraction.unwrap_or(0.01),
75|        }
76|    }
77|}
