89|
90|#[pyclass]
91|#[derive(Clone, Debug)]
92|pub struct BrokerPosition {
93|    #[pyo3(get)]
94|    pub instrument_id: String,
95|    #[pyo3(get)]
96|    pub side: String,
97|    #[pyo3(get)]
98|    pub quantity: i64,
99|}
