113|// ─── ReconciliationEngine ────────────────────────────────────────────────────────
114|
115|#[pyclass]
116|#[derive(Clone, Debug)]
117|pub struct ReconciliationEngine {
118|    config: ReconciliationConfig,
119|}
120|
121|#[pymethods]
122|impl ReconciliationEngine {
123|    #[new]
124|    #[pyo3(signature = (config=None))]
125|    pub fn new(config: Option<ReconciliationConfig>) -> Self {
126|        Self {
127|            config: config.unwrap_or_default(),
128|        }
129|    }
130|
131|    pub fn compare(
132|        &self,
133|        portfolio: &PortfolioEngine,
134|        broker_positions: Vec<BrokerPosition>,
135|        broker_cash: &Money,
136|    ) -> ReconciliationResult {
137|        let broker_map: HashMap<&str, &BrokerPosition> = broker_positions
138|            .iter()
139|            .map(|bp| (bp.instrument_id.as_str(), bp))
140|            .collect();
141|
142|        let mut position_drifts: Vec<PositionDrift> = Vec::new();
143|
144|        for (inst_id, pos) in &portfolio.positions {
145|            let broker_pos = broker_map.get(inst_id.as_str());
146|            let (expected_side, expected_qty) = signed_position(pos.side, pos.quantity);
147|            let (actual_side, actual_qty) = match broker_pos {
148|                Some(bp) => (bp.side.clone(), signed_broker(&bp.side, bp.quantity)),
149|                None => ("FLAT".to_string(), 0),
150|            };
151|            let quantity_drift = (expected_qty - actual_qty).unsigned_abs() as i64;
152|            position_drifts.push(PositionDrift {
153|                instrument_id: inst_id.clone(),
154|                expected_side,
155|                expected_quantity: expected_qty,
156|                actual_side,
157|                actual_quantity: actual_qty,
158|                quantity_drift,
159|            });
160|        }
161|
162|        for bp in &broker_positions {
163|            if !portfolio.positions.contains_key(&bp.instrument_id) {
164|                let (actual_side, actual_qty) = (bp.side.clone(), signed_broker(&bp.side, bp.quantity));
165|                position_drifts.push(PositionDrift {
166|                    instrument_id: bp.instrument_id.clone(),
167|                    expected_side: "FLAT".to_string(),
168|                    expected_quantity: 0,
169|                    actual_side,
170|                    actual_quantity: actual_qty,
171|                    quantity_drift: actual_qty.unsigned_abs() as i64,
172|                });
173|            }
174|        }
175|
176|        let cash_expected = portfolio.get_cash_balance();
177|        let cash_actual = broker_cash.clone();
178|        let cash_drift_amount = (cash_expected.amount - cash_actual.amount).abs();
179|
180|        // Determine severity
181|        let severity = self.compute_severity(&position_drifts, cash_expected.amount, cash_actual.amount);
182|
183|        let summary = format!(
184|            "Reconciliation: {:?} — {} position drift(s), cash drift {}",
185|            severity,
186|            position_drifts.len(),
187|            cash_drift_amount,
188|        );
189|
190|        let cash_drift = Money { amount: cash_drift_amount, currency: cash_expected.currency.clone() };
191|
192|        ReconciliationResult {
193|            severity,
194|            position_drifts,
195|            cash_expected,
196|            cash_actual,
197|            cash_drift,
198|            summary,
199|        }
200|    }
201|}
202|
203|impl ReconciliationEngine {
204|    fn compute_severity(
205|        &self,
206|        drifts: &[PositionDrift],
207|        cash_exp_amount: Decimal,
208|        cash_act_amount: Decimal,
209|    ) -> ReconciliationDriftSeverity {
210|        let mut severity = ReconciliationDriftSeverity::InSync;
211|
212|        for pd in drifts {
213|            let max_qty = pd
214|                .expected_quantity
215|                .abs()
216|                .max(pd.actual_quantity.abs())
217|                .max(1);
218|            let drift_fraction = pd.quantity_drift as f64 / max_qty as f64;
219|
220|            if drift_fraction > self.config.critical_drift_fraction {
221|                return ReconciliationDriftSeverity::Critical;
222|            }
223|            if drift_fraction > self.config.warning_drift_fraction {
224|                severity = ReconciliationDriftSeverity::Warning;
225|            }
226|        }
227|
228|        // Cash drift check
229|        if severity != ReconciliationDriftSeverity::Critical {
230|            let cash_drift_amount = (cash_exp_amount - cash_act_amount).abs();
231|            let max_cash = cash_exp_amount
232|                .abs()
233|                .max(cash_act_amount.abs())
234|                .max(Decimal::ONE);
235|            let cash_drift_fraction = cash_drift_amount.to_f64().unwrap_or(0.0) / max_cash.to_f64().unwrap_or(1.0);
236|
237|            if cash_drift_fraction > self.config.critical_drift_fraction {
238|                return ReconciliationDriftSeverity::Critical;
239|            }
240|            if cash_drift_fraction > self.config.warning_drift_fraction {
241|                severity = ReconciliationDriftSeverity::Warning;
242|            }
243|        }
244|
245|        severity
246|    }
247|}
