249|// ─── Private helpers ─────────────────────────────────────────────────────────────
250|
251|fn signed_broker(side: &str, quantity: i64) -> i64 {
252|    match side {
253|        "LONG" => quantity,
254|        "SHORT" => -quantity.abs(),
255|        _ => 0,
256|    }
257|}
258|
259|fn signed_position(side: PositionSide, quantity: u64) -> (String, i64) {
260|    match side {
261|        PositionSide::Flat => ("FLAT".to_string(), 0),
262|        PositionSide::Long => ("LONG".to_string(), quantity as i64),
263|        PositionSide::Short => ("SHORT".to_string(), -(quantity as i64)),
264|    }
265|}
