27|/// Validates that the string contains a valid decimal representation (no NaN, inf, or arbitrary characters).
28|pub fn deserialize_decimal_string<'de, D>(deserializer: D) -> Result<String, D::Error>
29|where
30|    D: Deserializer<'de>,
31|{
32|    let s = String::deserialize(deserializer)?;
33|    
34|    if s.is_empty() {
35|        return Err(serde::de::Error::custom("decimal string cannot be empty"));
36|    }
37|    
38|    let mut chars = s.chars().peekable();
39|    if chars.peek() == Some(&'-') {
40|        chars.next();
41|    }
42|    
43|    let mut has_integer_digits = false;
44|    let mut has_fractional_digits = false;
45|    let mut has_dot = false;
46|    
47|    for c in chars {
48|        if c == '.' {
49|            if has_dot {
50|                return Err(serde::de::Error::custom("multiple dots in decimal string"));
51|            }
52|            has_dot = true;
53|        } else if c.is_ascii_digit() {
54|            if has_dot {
55|                has_fractional_digits = true;
56|            } else {
57|                has_integer_digits = true;
58|            }
59|        } else {
60|            return Err(serde::de::Error::custom(format!("invalid character '{}' in decimal string", c)));
61|        }
62|    }
63|    
64|    if !has_integer_digits && !has_fractional_digits {
65|        return Err(serde::de::Error::custom("decimal string requires digits"));
66|    }
67|    
68|    if Decimal::from_str(&s).is_err() {
69|        return Err(serde::de::Error::custom("failed to parse decimal value"));
70|    }
71|
72|    Ok(s)
