81|#[pymethods]
82|impl PortfolioEngine {
83|    #[new]
84|    pub fn new(base_currency: &str, initial_cash: &Money) -> Self {
85|        let initial_amount = initial_cash.amount;
86|        Self {
87|            positions: HashMap::new(),
88|            cash_balance: initial_cash.clone(),
89|            base_currency: base_currency.to_string(),
90|            realized_pnl: Money::new("0", base_currency),
91|            peak_total_value: initial_amount,
92|            daily_realized_loss: Decimal::ZERO,
93|            loss_date: String::new(),
94|            market_prices: HashMap::new(),
95|        }
96|    }
