98|    /// Apply a fill to the portfolio, updating position and cash.
99|    ///
100|    /// `side` must be "buy" or "sell" (case-insensitive).
101|    /// `quantity` is the number of contracts/shares.
102|    /// `price` is the fill price per unit.
103|    pub fn apply_fill(
104|        &mut self,
105|        instrument_id: &str,
106|        side: &str,
107|        quantity: u64,
108|        price: &Money,
109|    ) -> PyResult<()> {
110|        let side_lower = side.to_lowercase();
111|        let is_buy = side_lower == "buy";
112|        if !is_buy && side_lower != "sell" {
113|            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
114|                "side must be 'buy' or 'sell'",
115|            ));
116|        }
117|
118|        if quantity == 0 {
119|            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
120|                "quantity must be non-zero",
121|            ));
122|        }
123|
124|        let qty = Decimal::from(quantity);
125|        let notional = price.amount * qty;
126|
127|        // Update cash: buys decrease, sells increase
128|        let new_cash = if is_buy {
129|            self.cash_balance.amount.checked_sub(notional)
130|        } else {
131|            self.cash_balance.amount.checked_add(notional)
132|        };
133|        let new_cash = match new_cash {
134|            Some(v) => v,
135|            None => return Err(PyErr::new::<pyo3::exceptions::PyOverflowError, _>(
136|                "cash balance overflow",
137|            )),
138|        };
139|        self.cash_balance.amount = new_cash;
140|
141|        let position = self.positions.get_mut(instrument_id);
142|
143|        if let Some(pos) = position {
144|            // Existing position — apply lifecycle logic
145|            match (pos.side, is_buy) {
146|                (PositionSide::Long, true) => {
147|                    // Adding to long: weighted average cost basis
148|                    let old_total = pos.cost_basis.amount * Decimal::from(pos.quantity);
149|                    let new_total = old_total + notional;
150|                    let new_qty = pos.quantity + quantity;
151|                    let new_cost = new_total / Decimal::from(new_qty);
152|                    pos.quantity = new_qty;
153|                    pos.cost_basis.amount = new_cost;
154|                }
155|                (PositionSide::Long, false) => {
156|                    // Selling from long
157|                    let pnl_per_unit = price.amount - pos.cost_basis.amount;
158|                    let pnl_qty = Decimal::from(quantity.min(pos.quantity));
159|                    let pnl = pnl_per_unit * pnl_qty;
160|                    if quantity < pos.quantity {
161|                        pos.quantity -= quantity;
162|                    } else if quantity == pos.quantity {
163|                        pos.side = PositionSide::Flat;
164|                        pos.quantity = 0;
165|                        pos.cost_basis.amount = Decimal::ZERO;
166|                    } else {
167|                        let excess = quantity - pos.quantity;
168|                        pos.side = PositionSide::Short;
169|                        pos.quantity = excess;
170|                        pos.cost_basis.amount = price.amount;
171|                    }
172|                    self.add_pnl(pnl);
173|                }
174|                (PositionSide::Short, false) => {
175|                    // Adding to short: weighted average cost basis
176|                    let old_total = pos.cost_basis.amount * Decimal::from(pos.quantity);
177|                    let new_total = old_total + notional;
178|                    let new_qty = pos.quantity + quantity;
179|                    let new_cost = new_total / Decimal::from(new_qty);
180|                    pos.quantity = new_qty;
181|                    pos.cost_basis.amount = new_cost;
182|                }
183|                (PositionSide::Short, true) => {
184|                    // Buying to cover short
185|                    let pnl_per_unit = pos.cost_basis.amount - price.amount;
186|                    let pnl_qty = Decimal::from(quantity.min(pos.quantity));
187|                    let pnl = pnl_per_unit * pnl_qty;
188|                    if quantity < pos.quantity {
189|                        pos.quantity -= quantity;
190|                    } else if quantity == pos.quantity {
191|                        pos.side = PositionSide::Flat;
192|                        pos.quantity = 0;
193|                        pos.cost_basis.amount = Decimal::ZERO;
194|                    } else {
195|                        let excess = quantity - pos.quantity;
196|                        pos.side = PositionSide::Long;
197|                        pos.quantity = excess;
198|                        pos.cost_basis.amount = price.amount;
199|                    }
200|                    self.add_pnl(pnl);
201|                }
202|                (PositionSide::Flat, _) => {
203|                    pos.side = if is_buy { PositionSide::Long } else { PositionSide::Short };
204|                    pos.quantity = quantity;
205|                    pos.cost_basis.amount = price.amount;
206|                }
207|            }
208|        } else {
209|            // No existing position — create a new one
210|            let side_enum = if is_buy {
211|                PositionSide::Long
212|            } else {
213|                PositionSide::Short
214|            };
215|            let pos = Position {
216|                instrument_id: instrument_id.to_string(),
217|                side: side_enum,
218|                quantity,
219|                cost_basis: Money { amount: price.amount, currency: self.base_currency.clone() },
220|            };
221|            self.positions.insert(instrument_id.to_string(), pos);
222|        }
223|
224|        Ok(())
225|    }
226|
227|    /// Get the position for an instrument, or None if not held.
228|    pub fn get_position(&self, instrument_id: &str) -> Option<Position> {
229|        self.positions.get(instrument_id).cloned()
230|    }
231|
232|    pub fn get_cash_balance(&self) -> Money {
233|        self.cash_balance.clone()
234|    }
235|
236|    pub fn get_realized_pnl(&self) -> Money {
237|        self.realized_pnl.clone()
238|    }
239|
240|    pub fn set_realized_pnl(&mut self, pnl: &Money) {
241|        self.realized_pnl.amount = pnl.amount;
242|    }
243|
244|    /// Compute unrealized PnL for a given instrument at `current_price`.
245|    /// Returns 0 if the position is Flat.
246|    pub fn get_unrealized_pnl(
247|        &self,
248|        instrument_id: &str,
249|        current_price: &Money,
250|    ) -> PyResult<Money> {
251|        let pos = self.positions.get(instrument_id).ok_or_else(|| {
252|            PyErr::new::<pyo3::exceptions::PyKeyError, _>(
253|                format!("No position for instrument '{}'", instrument_id),
254|            )
255|        })?;
256|
257|        let pnl_per_unit = match pos.side {
258|            PositionSide::Long => current_price.amount - pos.cost_basis.amount,
259|            PositionSide::Short => pos.cost_basis.amount - current_price.amount,
260|            PositionSide::Flat => Decimal::ZERO,
261|        };
262|        let total_pnl = pnl_per_unit * Decimal::from(pos.quantity);
263|        Ok(Money { amount: total_pnl, currency: self.base_currency.clone() })
264|    }
265|
266|    /// Sum of absolute position values using market price (M2M) with cost-basis fallback.
267|    pub fn total_gross_exposure(&self) -> Money {
268|        let mut total = Decimal::ZERO;
269|        for pos in self.positions.values() {
270|            let price = self.market_prices
271|                .get(&pos.instrument_id)
272|                .and_then(|p| Decimal::from_str(p).ok())
273|                .unwrap_or(pos.cost_basis.amount);
274|            total += price * Decimal::from(pos.quantity);
275|        }
276|        Money { amount: total, currency: self.base_currency.clone() }
277|    }
278|
279|    /// Build a portfolio snapshot of the current state.
280|    pub fn get_snapshot(&self) -> PortfolioSnapshot {
281|        let dd = self.drawdown_fraction();
282|        PortfolioSnapshot {
283|            gross_exposure: self.total_gross_exposure(),
284|            drawdown_fraction: dd,
285|            daily_realized_loss: Money { amount: self.daily_realized_loss, currency: self.base_currency.clone() },
286|            position_size: self.positions.len() as u64,
287|        }
288|    }
289|
290|    pub fn drawdown_fraction(&self) -> f64 {
291|        let total = self.total_value();
292|        if self.peak_total_value <= Decimal::ZERO || total <= Decimal::ZERO {
293|            return 0.0;
294|        }
295|        let dd = (self.peak_total_value - total) / self.peak_total_value;
296|        dd.to_f64().unwrap_or(0.0).max(0.0)
297|    }
298|
299|    pub fn get_daily_loss(&self) -> Money {
300|        Money { amount: self.daily_realized_loss, currency: self.base_currency.clone() }
301|    }
302|
303|    /// Store a market price and recalculate peak total value for drawdown tracking.
304|    pub fn update_market_price(&mut self, instrument_id: &str, price: &str) -> PyResult<()> {
305|        // Validate price is parseable
306|        let _ = Decimal::from_str(price).map_err(|e| {
307|            pyo3::exceptions::PyValueError::new_err(format!("Invalid market price '{}': {}", price, e))
308|        })?;
309|        self.market_prices.insert(instrument_id.to_string(), price.to_string());
310|        let total = self.total_value();
311|        if total > self.peak_total_value {
312|            self.peak_total_value = total;
313|        }
314|        Ok(())
315|    }
316|
317|    /// Bulk update market prices.
318|    pub fn update_market_prices(&mut self, prices: Vec<(String, String)>) -> PyResult<()> {
319|        for (instrument_id, price) in prices {
320|            self.update_market_price(&instrument_id, &price)?;
321|        }
322|        Ok(())
323|    }
