328|impl PortfolioEngine {
329|    fn add_pnl(&mut self, amount: Decimal) {
330|        self.realized_pnl.amount += amount;
331|        // Track peak total value for drawdown
332|        let total = self.total_value();
333|        if total > self.peak_total_value {
334|            self.peak_total_value = total;
335|        }
336|        // Track daily realized loss
337|        if amount < Decimal::ZERO {
338|            let today = Utc::now().format("%Y-%m-%d").to_string();
339|            if self.loss_date != today {
340|                self.loss_date = today;
341|                self.daily_realized_loss = Decimal::ZERO;
342|            }
343|            self.daily_realized_loss += amount;
344|        }
345|    }
346|
347|    fn total_value(&self) -> Decimal {
348|        let mut total = self.cash_balance.amount;
349|        for pos in self.positions.values() {
350|            let price = self.market_prices
351|                .get(&pos.instrument_id)
352|                .and_then(|p| Decimal::from_str(p).ok())
353|                .unwrap_or(pos.cost_basis.amount);
354|            match pos.side {
355|                PositionSide::Long => total += price * Decimal::from(pos.quantity),
356|                PositionSide::Short => total -= price * Decimal::from(pos.quantity),
357|                PositionSide::Flat => {}
358|            }
359|        }
360|        total
361|    }
