617|                            reason: Some(RiskReasonCode::CorrelatedExposureExceeded),
618|                            reason_detail: format!(
619|                                "Mean correlation {:.4} exceeds max {:.2}",
620|                                mean, self.config.max_correlated_exposure,
621|                            ),
622|                        });
623|                    }
624|                }
625|            }
626|            None
627|        }
628|
629|    pub fn set_trading_state(&mut self, state: TradingState) -> PyResult<()> {
630|        self.trading_state
631|            .transition(state)
632|            .map_err(pyo3::exceptions::PyValueError::new_err)
633|    }
634|
635|    pub fn trigger_kill_switch(&mut self) -> PyResult<()> {
636|        self.kill_switch
637|            .transition(KillSwitchState::Triggered)
638|            .map_err(pyo3::exceptions::PyValueError::new_err)
639|    }
640|
641|    pub fn release_initiated(&mut self) -> PyResult<()> {
642|        self.kill_switch
643|            .transition(KillSwitchState::Releasing)
644|            .map_err(pyo3::exceptions::PyValueError::new_err)
645|    }
646|
647|    pub fn release_completed(&mut self) -> PyResult<()> {
648|        self.kill_switch
649|            .transition(KillSwitchState::Released)
650|            .map_err(pyo3::exceptions::PyValueError::new_err)
651|    }
652|
653|    pub fn persist_state(&mut self, store: &event_store::EventStore) -> PyResult<()> {
654|        let snapshot = RiskStateSnapshot {
655|            message_id: format!("snap-{}", Uuid::now_v7()),
656|            kill_switch_state: format!("{:?}", self.kill_switch),
657|            trading_state: format!("{:?}", self.trading_state),
658|            occurred_at: Utc::now().to_rfc3339(),
659|        };
660|        let json = serde_json::to_string(&snapshot).map_err(|e| {
661|            PyRuntimeError::new_err(format!("Serialize error: {}", e))
662|        })?;
663|        let envelope = EventEnvelope::new(
664|            "RiskStateSnapshot".to_string(),
665|            "RiskGate".to_string(),
666|            "system".to_string(),
667|            "titan_core".to_string(),
668|            json,
669|            None, None, None,
670|        );
671|        store.append(&envelope)
672|    }
673|
674|    pub fn restore_state(&mut self, store: &event_store::EventStore) -> PyResult<()> {
675|        let events = store.replay_by_type("RiskStateSnapshot")?;
676|        if let Some(latest) = events.last() {
677|            if let Ok(snapshot) = serde_json::from_str::<RiskStateSnapshot>(&latest.payload) {
678|                self.kill_switch = serde_json::from_str(&format!("\"{}\"", snapshot.kill_switch_state))
679|                    .unwrap_or(KillSwitchState::Triggered);
680|                self.trading_state = serde_json::from_str(&format!("\"{}\"", snapshot.trading_state))
681|                    .unwrap_or(TradingState::Halted);
682|            }
683|        }
684|        Ok(())
685|    }
686|
687|    #[staticmethod]
688|    pub fn load_or_default(config: RiskConfig, store: &event_store::EventStore) -> PyResult<RiskGate> {
689|        let mut gate = RiskGate::new(config);
690|        Self::apply_snapshot(&mut gate, store)?;
691|        Ok(gate)
692|    }
693|}
694|
695|impl RiskGate {
696|    fn apply_snapshot(gate: &mut RiskGate, store: &event_store::EventStore) -> PyResult<()> {
697|        let events = store.replay_by_type("RiskStateSnapshot")?;
698|        if let Some(latest) = events.last() {
699|            let snapshot: RiskStateSnapshot = serde_json::from_str(&latest.payload).map_err(|e| {
700|                PyRuntimeError::new_err(format!("Deserialize error: {}", e))
701|            })?;
702|            gate.kill_switch = serde_json::from_str(&format!("\"{}\"", snapshot.kill_switch_state))
703|                .unwrap_or(KillSwitchState::Triggered);
704|            gate.trading_state = serde_json::from_str(&format!("\"{}\"", snapshot.trading_state))
705|                .unwrap_or(TradingState::Halted);
706|        } else {
707|            gate.kill_switch = KillSwitchState::Triggered;
708|            gate.trading_state = TradingState::Halted;
709|        }
710|        Ok(())
711|    }
712|}
