pub enum Side {
    Buy,
    Sell,
}

#[pymethods]
impl Side {
    fn __str__(&self) -> String {
        format!("{:?}", self)
    }

    fn __repr__(&self) -> String {
        format!("Side.{:?}", self)
    }
}

/// A fixed-decimal monetary value with an explicit currency.
#[pyclass(from_py_object)]
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Money {
    #[serde(with = "rust_decimal::serde::str")]
    pub(crate) amount: Decimal,
    #[pyo3(get)]
    pub currency: String,
}

impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} {}", self.amount, self.currency)
    }
}

#[pymethods]
impl Money {
    #[new]
    pub fn new(amount: &str, currency: &str) -> PyResult<Self> {
        let d = Decimal::from_str(amount).map_err(|e| {
            pyo3::exceptions::PyValueError::new_err(format!("Invalid amount '{}': {}", amount, e))
        })?;
        Ok(Self {
            amount: d,
            currency: currency.to_string(),
        })
    }

    #[getter]
    fn get_amount(&self) -> String {
        self.amount.to_string()
    }

    fn __str__(&self) -> String {
        self.to_string()
    }

    fn __repr(&self) -> String {
        format!("Money('{}', '{}')", self.amount, self.currency)
    }
}

