        })?;
        Ok(Self { value: d })
    }

    #[getter]
    fn get_value(&self) -> String {
        self.value.to_string()
    }

    fn __str__(&self) -> String {
        self.value.to_string()
    }

    fn __repr(&self) -> String {
        format!("Quantity('{}')", self.value)
    }
}

