585|                    accepted: false,
586|                    reason: Some(RiskReasonCode::SellExceedsPosition),
587|                    reason_detail: format!("Sell {} exceeds long position of {}", intent_qty, qty),
588|                });
589|            }
590|
591|            if intent.side == "BUY" && side_upper == "SHORT" && intent_qty > Decimal::from(qty) {
592|                return Some(RiskVerdict {
593|                    accepted: false,
594|                    reason: Some(RiskReasonCode::BuyExceedsShortPosition),
595|                    reason_detail: format!(
596|                        "Buy-to-cover {} exceeds short position of {}",
597|                        intent_qty, qty
598|                    ),
599|                });
600|            }
601|        }
602|        None
603|    }
604|
605|    /// l. Correlation check — rejects if mean correlation exceeds the configured limit.
606|        fn check_correlation(
607|            &self,
608|            _intent: &TradeIntent,
609|            correlation_scores: &Option<Vec<f64>>,
610|        ) -> Option<RiskVerdict> {
611|            if let Some(scores) = correlation_scores
612|                && !scores.is_empty()
613|            {
614|                let mean: f64 = scores.iter().sum::<f64>() / scores.len() as f64;
615|                if mean > self.config.max_correlated_exposure {
616|                    return Some(RiskVerdict {
617|                        accepted: false,
618|                        reason: Some(RiskReasonCode::CorrelatedExposureExceeded),
619|                        reason_detail: format!(
620|                            "Mean correlation {:.4} exceeds max {:.2}",
621|                            mean, self.config.max_correlated_exposure,
622|                        ),
623|                    });
624|                }
625|            }
626|            None
627|        }
628|
629|    fn apply_snapshot(gate: &mut RiskGate, store: &event_store::EventStore) -> PyResult<()> {
630|        let events = store.replay_by_type("RiskStateSnapshot")?;
631|        if let Some(latest) = events.last() {
632|            let snapshot: RiskStateSnapshot = serde_json::from_str(&latest.payload).map_err(|e| {
633|                PyRuntimeError::new_err(format!("Deserialize error: {}", e))
634|            })?;
635|            gate.kill_switch = serde_json::from_str(&format!("\"{}\"", snapshot.kill_switch_state))
636|                .unwrap_or(KillSwitchState::Triggered);
637|            gate.trading_state = serde_json::from_str(&format!("\"{}\"", snapshot.trading_state))
638|                .unwrap_or(TradingState::Halted);
639|        } else {
640|            gate.kill_switch = KillSwitchState::Triggered;
641|            gate.trading_state = TradingState::Halted;
642|        }
643|        Ok(())
644|    }
