11|/// Valid order states per EXECUTION_SPEC.md.
12|#[pyclass(eq, eq_int, from_py_object)]
13|#[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize)]
14|pub enum OrderState {
15|    #[default]
16|    New,
17|    Validated,
18|    Submitted,
19|    Acknowledged,
20|    PartiallyFilled,
21|    Filled,
22|    CancelPending,
23|    Cancelled,
24|    Rejected,
25|    Expired,
26|    Unknown,
27|}
28|
29|#[pymethods]
30|impl OrderState {
31|    fn __str__(&self) -> String {
32|        format!("{:?}", self)
33|    }
34|
35|    fn __repr__(&self) -> String {
36|        format!("OrderState.{:?}", self)
37|    }
38|
39|    pub fn is_terminal(&self) -> bool {
40|        matches!(
41|            self,
42|            OrderState::Filled
43|                | OrderState::Cancelled
44|                | OrderState::Rejected
45|                | OrderState::Expired
46|        )
47|    }
48|}
49|
50|/// Event payload for order state transitions persisted to EventStore.
51|#[derive(Serialize)]
52|pub struct OrderEvent {
53|    pub order_id: String,
54|    pub from_state: String,
55|    pub to_state: String,
56|    pub reason: String,
57|    pub occurred_at: String,
58|    pub message_id: String,
59|}
60|
61|/// Pure Rust state machine — no PyO3 dependency, testable from `cargo test`.
62|#[derive(Clone, Debug, Default)]
63|pub struct StateMachineCore {
64|    pub current: OrderState,
65|}
66|
67|impl StateMachineCore {
68|    pub fn new() -> Self {
69|        Self {
70|            current: OrderState::New,
71|        }
72|    }
73|
74|    pub fn transition(&mut self, target: OrderState) -> Result<(), String> {
75|        let from = self.current;
76|
77|        if from == target {
78|            return Ok(());
79|        }
80|
81|        if from.is_terminal() {
82|            return Err(format!(
83|                "Cannot transition from terminal state {:?} to {:?}",
84|                from, target
85|            ));
86|        }
87|
88|        let valid = match (from, target) {
89|            // Normal flow
90|            (OrderState::New, OrderState::Validated) => true,
91|            (OrderState::Validated, OrderState::Submitted) => true,
92|            (OrderState::Submitted, OrderState::Acknowledged) => true,
93|            (OrderState::Acknowledged, OrderState::PartiallyFilled) => true,
94|            (OrderState::Acknowledged, OrderState::Filled) => true,
95|            (OrderState::PartiallyFilled, OrderState::Filled) => true,
96|
97|
98|            // Rejection can happen from multiple states
99|            (OrderState::New, OrderState::Rejected) => true,
100|            (OrderState::Validated, OrderState::Rejected) => true,
101|            (OrderState::Submitted, OrderState::Rejected) => true,
102|            (OrderState::Acknowledged, OrderState::Rejected) => true,
103|
104|            // Cancellation
105|            (OrderState::Acknowledged, OrderState::CancelPending) => true,
106|            (OrderState::PartiallyFilled, OrderState::CancelPending) => true,
107|            (OrderState::CancelPending, OrderState::Cancelled) => true,
108|
109|            // Expiry
110|            (OrderState::Acknowledged, OrderState::Expired) => true,
111|            (OrderState::PartiallyFilled, OrderState::Expired) => true,
112|
113|            // Unknown (safety state on timeout/ambiguity)
114|            (OrderState::Submitted, OrderState::Unknown) => true,
115|            (OrderState::CancelPending, OrderState::Unknown) => true,
116|
117|            // Reconciliation from Unknown
118|            (OrderState::Unknown, OrderState::Acknowledged) => true,
119|            (OrderState::Unknown, OrderState::Filled) => true,
120|            (OrderState::Unknown, OrderState::Rejected) => true,
121|            (OrderState::Unknown, OrderState::Cancelled) => true,
122|            (OrderState::Unknown, OrderState::Expired) => true,
123|
124|            _ => false,
125|        };
126|
127|        if valid {
128|            self.current = target;
129|            Ok(())
130|        } else {
131|            Err(format!(
132|                "Illegal state transition: {:?} -> {:?}",
133|                from, target
134|            ))
135|        }
136|    }
137|
138|    pub fn reset_to(&mut self, state: OrderState) {
139|        self.current = state;
140|    }
141|}
