143|/// PyO3 wrapper — validates and applies state transitions for an order.
144|#[pyclass(from_py_object)]
145|#[derive(Clone, Debug, Default)]
146|pub struct OrderStateMachine {
147|    inner: StateMachineCore,
148|}
149|
150|#[pymethods]
151|impl OrderStateMachine {
152|    #[new]
153|    pub fn new() -> Self {
154|        Self {
155|            inner: StateMachineCore::new(),
156|        }
157|    }
158|
159|    #[getter]
160|    pub fn get_current(&self) -> OrderState {
161|        self.inner.current
162|    }
163|
164|    pub fn transition(&mut self, target: OrderState) -> PyResult<()> {
165|        self.inner.transition(target).map_err(PyValueError::new_err)
166|    }
167|
168|    pub fn reset_to(&mut self, state: OrderState) {
169|        self.inner.reset_to(state);
170|    }
171|
172|    pub fn persist_transition(
173|        &self,
174|        store: &event_store::EventStore,
175|        order_id: &str,
176|        from: &OrderState,
177|        to: &OrderState,
178|        reason: &str,
179|    ) -> PyResult<()> {
180|        let now = Utc::now().to_rfc3339();
181|        let msg_id = Uuid::now_v7().to_string();
182|        let event = OrderEvent {
183|            order_id: order_id.to_string(),
184|            from_state: format!("{:?}", from),
185|            to_state: format!("{:?}", to),
186|            reason: reason.to_string(),
187|            occurred_at: now,
188|            message_id: msg_id,
189|        };
190|        let payload = serde_json::to_string(&event)
191|            .map_err(|e| PyRuntimeError::new_err(format!("Serialize error: {}", e)))?;
192|        let envelope = EventEnvelope::new(
193|            "OrderTransition".to_string(),
194|            "Order".to_string(),
195|            order_id.to_string(),
196|            "titan_core".to_string(),
197|            payload,
198|            None,
199|            None,
200|            None,
201|        );
202|        store.append(&envelope)
203|    }
204|
205|    fn __str__(&self) -> String {
206|        format!("OrderStateMachine({:?})", self.inner.current)
207|    }
