185|                    let pnl_per_unit = pos.cost_basis.amount - price.amount;
186|                    let pnl_qty = Decimal::from(quantity.min(pos.quantity));
187|                    let pnl = pnl_per_unit * pnl_qty;
188|                    if quantity < pos.quantity {
