            log(f"Killing {len(chrome_pids)} orphaned Chrome process(es) …")
            for pid in chrome_pids:
                try:
                    subprocess.run(
                        ["taskkill", "/F", "/PID", pid],
                        capture_output=True, timeout=5,
                    )
                except Exception:
                    pass
        else:
            log("No orphaned Chrome processes found.")
    except Exception as exc:
        log(f"Chrome cleanup note: {exc}")
        # Fallback: blanket kill of any chrome.exe processes
        try:
            subprocess.run(
                ["taskkill", "/F", "/IM", "chrome.exe"],
                capture_output=True, timeout=10,
            )
        except Exception:
            pass


# ── browser lifecycle ────────────────────────────────────────────────────

_playwright: pwa.Playwright | None = None
_browser_context: pwa.BrowserContext | None = None
_page: pwa.Page | None = None


async def _start_playwright() -> None:
    global _playwright
    if _playwright is None:
        log("Starting Playwright driver …")
        _playwright = await pwa.async_playwright().start()


async def _ensure_browser() -> None:
    global _browser_context, _page
    if _page is not None:
        try:
            _ = await _page.title()
            return
        except Exception:
            pass

    await _start_playwright()
    log("Launching persistent Chromium browser …")
    PROFILE_DIR.mkdir(parents=True, exist_ok=True)

    _browser_context = await _playwright.chromium.launch_persistent_context(
        user_data_dir=str(PROFILE_DIR),
        headless=True,
        channel=None,
        args=[
            "--disable-blink-features=AutomationControlled",
            "--no-first-run",
            "--no-default-browser-check",
            "--disable-sync",
        ],
        viewport={"width": 1280, "height": 800},
        locale="en-US",
        timezone_id="UTC",
        ignore_https_errors=True,
    )

    pages = _browser_context.pages
    _page = pages[0] if pages else await _browser_context.new_page()

    await _page.route(
        lambda url: any(x in url for x in [
            "telemetry", "analytics", "crash-report", "bugsnag",
            "sentry", "datadog", "fullstory", "hotjar",
        ]),
        lambda route: route.abort(),
    )
    log("Browser ready.")


async def _navigate_to_chatgpt() -> None:
    await _ensure_browser()
    log("Navigating to https://chatgpt.com …")
    await _page.goto("https://chatgpt.com", wait_until="domcontentloaded", timeout=NAV_TIMEOUT)
    try:
        await _page.wait_for_load_state("networkidle", timeout=15_000)
    except Exception:
        log("networkidle timeout (expected), continuing …")
    await asyncio.sleep(2)
    log("Page loaded.")


# ── state helpers ────────────────────────────────────────────────────────

def _state() -> dict:
    if STATE_FILE.exists():
        return json.loads(STATE_FILE.read_text(encoding="utf-8"))
    return {}


def _save_state(**kw: Any) -> None:
    data = _state()
    data.update(kw)
    STATE_FILE.write_text(json.dumps(data, indent=2), encoding="utf-8")


# ── chat input selectors (tried in order) ────────────────────────────────
# If ChatGPT changes its UI, add the new selector here first.
CHAT_INPUT_SELECTORS = [
    "#prompt-textarea",
    "textarea[placeholder*='message']",
    "textarea[placeholder*='Message']",
    "textarea[placeholder*='Send']",
    "form textarea",
    "main textarea",
    "[data-id='root'] textarea",
    "div.overflow-hidden textarea",
    "div[contenteditable='true']",
    "[role='textbox']",
]

LOGIN_SELECTORS = [
    "textarea#prompt-textarea, #prompt-textarea",
    "textarea[placeholder*='message']",
    "textarea[placeholder*='Message']",
    "textarea[placeholder*='Send']",
    "div[data-message-author-role]",
    "nav a[href='/gpts']",
    "[data-testid='conversation-turn']",
    "button:has-text('New chat'), button:has-text('New Chat')",
    "a:has-text('ChatGPT'), a:has-text('chatgpt')",
    "h1:has-text('ChatGPT')",
    "form textarea",
    "main textarea",
    "div.overflow-hidden textarea",
    "div[contenteditable='true']",
    "[role='textbox']",
]

STOP_BUTTON_SELECTORS = [
    "button:has-text('Stop')",
    "button[data-testid='stop-button']",
    "button[aria-label='Stop']",
    "button[aria-label='Stop generating']",
]

NEW_CHAT_SELECTORS = [
    "a:has-text('New chat')",
    "a:has-text('New Chat')",
    "button:has-text('New chat')",
    "button:has-text('New Chat')",
    "nav a[href='/']",
    "nav a[href='/chat']",
]

SEND_BUTTON_SELECTORS = [
    "button[data-testid='send-button']",
    "button:has(svg)",
    "button:has-text('Send')",
]


# ── login detection ──────────────────────────────────────────────────────

async def _is_logged_in() -> bool:
    try:
        for sel in LOGIN_SELECTORS:
            try:
                el = await _page.wait_for_selector(sel, timeout=3_000)
                if el:
                    log(f"Login indicator: {sel[:50]}")
                    return True
            except Exception:
                continue

        url = _page.url
        if any(x in url for x in ("login", "auth", "signup", "sign-in")):
            log("Login page detected")
            return False

        login_btns = await _page.query_selector_all("button:has-text('Log in'), a:has-text('Log in')")
        if login_btns:
            log("Login button found")
            return False

        log("Unknown state — returning False")
        return False
    except Exception as exc:
        log(f"Login check error: {exc}")
        return False


# ── chat input finding ───────────────────────────────────────────────────

async def _find_chat_input():
    """Find the chat input using multi-selector strategy."""
    for sel in CHAT_INPUT_SELECTORS:
        try:
            el = await _page.wait_for_selector(sel, timeout=3_000)
            if el and await el.is_visible():
                return el
        except Exception:
            continue
    # Last resort
    try:
        return await _page.query_selector("textarea:visible, [contenteditable='true']:visible")
    except Exception:
        return None


async def _wait_for_chat_ready(timeout: int = 30_000) -> bool:
    log("Waiting for chat input …")
    try:
        await _page.wait_for_function(
            """() => {
                const sel = '#prompt-textarea, textarea[placeholder*="message"], ' +
                    'textarea[placeholder*="Message"], textarea[placeholder*="Send"], ' +
                    'form textarea, main textarea, [data-id="root"] textarea, ' +
                    'div[contenteditable="true"], [role="textbox"]';
                const inputs = document.querySelectorAll(sel);
                for (const el of inputs) {
                    const s = window.getComputedStyle(el);
                    if (s.display !== 'none' && s.visibility !== 'hidden' && !el.disabled)
                        return true;
                }
                return false;
            }""",
            timeout=timeout,
        )
        return True
    except Exception as exc:
        log(f"Chat input not found: {exc}")
        return False


async def _ensure_logged_in() -> tuple[bool, str]:
    await _navigate_to_chatgpt()
    if await _is_logged_in():
        ready = await _wait_for_chat_ready()
        return (True, "Logged in and ready.") if ready else (True, "Logged in, input may still load.")

    msg = (
        "⚠️  Not logged into ChatGPT.\n\n"
        "A browser window has opened. Please:\n"
        "1. Log in to your ChatGPT account in the browser window\n"
        "2. Complete any CAPTCHA or 2FA if needed\n"
        "3. Wait until you see the main ChatGPT chat interface\n\n"
        "I will detect the login and continue automatically."
    )
    log(msg)

    deadline = time.monotonic() + 300
    while time.monotonic() < deadline:
        await asyncio.sleep(SETUP_POLL_INTERVAL)
        if await _is_logged_in():
            _save_state(logged_in=True)
            await asyncio.sleep(1)
            ready = await _wait_for_chat_ready()
            return True, "Login detected! ChatGPT is now ready."
        url = _page.url
        if "chat" in url and "login" not in url:
            continue

    return False, "Login timeout (5 min)."


# ── message sending ──────────────────────────────────────────────────────

async def _type_into_chat(message: str) -> None:
    log("Typing message …")
    textarea = await _find_chat_input()
    if not textarea:
        raise RuntimeError("Could not find chat input field")

    await textarea.click()
    await asyncio.sleep(0.3)
    await textarea.fill("")
    await asyncio.sleep(0.2)
    await textarea.type(message, delay=10)
    log("Message typed.")


async def _send_message_via_enter() -> None:
    log("Sending message …")
    for sel in SEND_BUTTON_SELECTORS:
        try:
            btn = await _page.wait_for_selector(sel, timeout=2_000)
            if btn and await btn.is_visible():
                await btn.click()
                log("Send button clicked.")
                return
        except Exception:
            continue
    await _page.keyboard.press("Enter")
    log("Enter pressed.")


# ── response extraction ──────────────────────────────────────────────────

async def _extract_response_text() -> str:
    try:
        text = await _page.evaluate("""() => {
            const turns = document.querySelectorAll('[data-message-author-role="assistant"]');
            if (!turns || turns.length === 0) return '';
            const last = turns[turns.length - 1];
            const article = last.querySelector('article');
            if (article) return article.innerText;
            const md = last.querySelector('.markdown, .prose, [class*="markdown"]');
            if (md) return md.innerText;
            const content = last.querySelector('[data-message-content], [class*="message-content"]');
            if (content) return content.innerText;
            return last.innerText;
        }""")
        return text.strip() if text else ""
    except Exception as exc:
        log(f"Extract error: {exc}")
        return ""


async def _wait_for_response() -> str:
    log("Waiting for response …")
    await asyncio.sleep(1)

    try:
        await _page.wait_for_function(
            """() => document.querySelectorAll('[data-message-author-role="assistant"]').length > 0""",
            timeout=MSG_TIMEOUT,
        )
    except Exception as exc:
        log(f"Warning: timeout waiting for response start: {exc}")

    log("Monitoring response stream …")
    deadline = time.monotonic() + (MSG_TIMEOUT / 1000)
    last_text = ""
    stable_count = 0

    while time.monotonic() < deadline:
        await asyncio.sleep(1)

        stop_found = False
        for sel in STOP_BUTTON_SELECTORS:
            try:
                btn = await _page.query_selector(sel)
                if btn and await btn.is_visible():
                    stop_found = True
                    break
            except Exception:
                continue

        current = await _extract_response_text()

        if not stop_found:
            if current and current != last_text:
                last_text = current
                stable_count = 0
            elif current:
                stable_count += 1
                if stable_count >= 3:
                    log("Response stable for 3s")
                    break
            else:
                stable_count += 1
                if stable_count >= 5:
                    log("No response detected")
                    break
        else:
            if current:
                last_text = current
            stable_count = 0

    result = await _extract_response_text()
    log(f"Response captured ({len(result)} chars)")
    return result


# ── browser-use AI fallback ──────────────────────────────────────────────

async def _handle_send_message_browser_use(message: str) -> str | None:
    """Try using Browser Use Agent if available."""
    if not _HAVE_BROWSER_USE:
        return None
    try:
        agent = BUAgent(
            task=(
                f"You are on chatgpt.com. Type this message into the ChatGPT input and send it: "
                f"{json.dumps(message)}. "
                f"Wait for the complete response, then return its full text verbatim."
            ),
            controller=BUController(),
            use_vision=False,
            generate_gif=False,
        )
        result = await agent.run(max_steps=20)
        text = str(result)
        if text and text != "None" and len(text) > 10:
            return text
    except Exception as exc:
        log(f"Browser Use failed: {exc}")
    return None


# ── tool handlers ─────────────────────────────────────────────────────────

async def _handle_send_message(message: str) -> CallToolResult:
    logged_in, status_msg = await _ensure_logged_in()
    if not logged_in:
        return CallToolResult(content=[TextContent(type="text", text=status_msg)])

    # Try Browser Use AI agent first if available
    if _HAVE_BROWSER_USE:
        ai_response = await _handle_send_message_browser_use(message)
        if ai_response:
            return CallToolResult(content=[TextContent(type="text", text=ai_response)])

    # Fallback: direct Playwright
    await _type_into_chat(message)
    await _send_message_via_enter()
    response = await _wait_for_response()

    if not response:
        return CallToolResult(
            content=[TextContent(type="text", text="ChatGPT did not return a response.")]
        )
    return CallToolResult(content=[TextContent(type="text", text=response)])


async def _handle_new_chat(**_: Any) -> CallToolResult:
    logged_in, status_msg = await _ensure_logged_in()
    if not logged_in:
        return CallToolResult(content=[TextContent(type="text", text=status_msg)])

    try:
        for sel in NEW_CHAT_SELECTORS:
            try:
                btn = await _page.wait_for_selector(sel, timeout=3_000)
                if btn:
                    await btn.click()
                    break
            except Exception:
                continue
        else:
            await _page.keyboard.press("Control+Shift+O")
            await asyncio.sleep(1)
            if "new" not in _page.url:
                await _page.goto("https://chatgpt.com", wait_until="domcontentloaded")
    except Exception as exc:
        log(f"New chat: {exc}")
        await _page.goto("https://chatgpt.com", wait_until="domcontentloaded")

    await asyncio.sleep(2)
    return CallToolResult(content=[TextContent(type="text", text="Started a new ChatGPT conversation.")])


async def _handle_get_status(**_: Any) -> CallToolResult:
    parts = []
    try:
        await _ensure_browser()
        await _navigate_to_chatgpt()
        parts.append(f"URL: {_page.url}")
        li = await _is_logged_in()
        parts.append(f"Logged in: {'✅ Yes' if li else '❌ No'}")
        if li:
            ready = await _wait_for_chat_ready(timeout=10_000)
            parts.append(f"Chat ready: {'✅ Yes' if ready else '❌ No'}")
            title_result = await _handle_get_title()
            parts.append(f"Conversation: {title_result.content[0].text}")
        parts.append("Browser: Chromium (headless)")
    except Exception as exc:
        parts.append(f"Error: {exc}")
    return CallToolResult(content=[TextContent(type="text", text="\n".join(parts))])


async def _handle_get_title(**_: Any) -> CallToolResult:
    try:
        await _ensure_browser()
        title = await _page.evaluate("""() => {
            const h1 = document.querySelector('h1');
            if (h1 && h1.innerText.trim()) return h1.innerText.trim();
            const t = document.title;
            if (t && t !== 'ChatGPT') return t;
            const navs = document.querySelectorAll('nav a, [class*="breadcrumb"]');
            for (const el of navs) {
                if (el.innerText.trim()) return el.innerText.trim();
            }
            return 'Untitled conversation';
        }""")
        return CallToolResult(content=[TextContent(type="text", text=title)])
    except Exception as exc:
        return CallToolResult(content=[TextContent(type="text", text=f"Title error: {exc}")])


# ── MCP server ────────────────────────────────────────────────────────────

server = Server("chatgpt-mcp")


@server.list_tools()
async def list_tools() -> list[Tool]:
    return [
        Tool(
            name="chatgpt_send_message",
            description="Send a message to ChatGPT and return the full text response. "
                        "Waits for streaming to complete.",
            inputSchema={
                "type": "object",
                "properties": {
                    "message": {
                        "type": "string",
                        "description": "The message to send to ChatGPT",
                    },
                },
                "required": ["message"],
            },
        ),
        Tool(
            name="chatgpt_new_chat",
            description="Start a fresh ChatGPT conversation.",
            inputSchema={"type": "object", "properties": {}},
        ),
        Tool(
            name="chatgpt_get_status",
            description="Check ChatGPT status: login, URL, conversation title.",
            inputSchema={"type": "object", "properties": {}},
        ),
        Tool(
            name="chatgpt_get_title",
            description="Get the current conversation title.",
            inputSchema={"type": "object", "properties": {}},
        ),
    ]


@server.call_tool()
async def call_tool(name: str, arguments: dict) -> CallToolResult:
    try:
        handlers = {
            "chatgpt_send_message": _handle_send_message,
            "chatgpt_new_chat": _handle_new_chat,
            "chatgpt_get_status": _handle_get_status,
            "chatgpt_get_title": _handle_get_title,
        }
        handler = handlers.get(name)
        if not handler:
            raise ValueError(f"Unknown tool: {name}")
        return await handler(**arguments)
    except Exception as exc:
        log(f"Tool error ({name}): {exc}")
        return CallToolResult(
            content=[TextContent(type="text", text=f"Error: {exc}")],
            isError=True,
        )


# ── cleanup ──────────────────────────────────────────────────────────────

async def _cleanup() -> None:
    """Clean up browser and Playwright resources so no orphan processes remain."""
    global _page, _browser_context, _playwright
    log("Cleaning up browser resources …")

    # Close the page
    if _page is not None:
        try:
            await _page.close()
        except Exception:
            pass
        _page = None

    # Close the persistent browser context
    if _browser_context is not None:
        try:
            await _browser_context.close()
        except Exception:
            pass
        _browser_context = None

    # Stop Playwright (kills node.exe + chrome.exe)
    if _playwright is not None:
        try:
            await _playwright.stop()
        except Exception:
            pass
        _playwright = None

    # Extra safety: kill any remaining Chrome processes that might have our profile
    _kill_orphan_chrome_processes()


# ── entry point ──────────────────────────────────────────────────────────

async def main() -> None:
    log("=" * 60)
    eng = "Browser Use" if _HAVE_BROWSER_USE else "Playwright"
    log(f"ChatGPT MCP Server starting ({eng} engine) …")

    # Pre-cleanup: kill any orphaned Chrome instances before launching our own
    _kill_orphan_chrome_processes()

    try:
        await _ensure_browser()
        log(f"State file: {json.dumps(_state())}")
    except Exception as exc:
        log(f"Browser pre-init deferred: {exc}")

    log("MCP server ready. Starting stdio transport …")

    from mcp.server.stdio import stdio_server

    try:
        async with stdio_server() as (read_stream, write_stream):
            await server.run(
                read_stream,
                write_stream,
                InitializationOptions(
                    server_name="chatgpt-mcp",
                    server_version="2.0.0",
                    capabilities=server.get_capabilities(
                        notification_options=NotificationOptions(),
                        experimental_capabilities={},
                    ),
                ),
            )
    except Exception as exc:
        log(f"Server transport error: {type(exc).__name__}: {exc}")
        raise
    finally:
        await _cleanup()


if __name__ == "__main__":
    # Register signal handlers so we clean up Chrome on forced termination
    loop = asyncio.new_event_loop()
    try:
        loop.run_until_complete(main())
    except KeyboardInterrupt:
        log("Shutting down (KeyboardInterrupt).")
        loop.run_until_complete(_cleanup())
    except asyncio.CancelledError:
        log("Shutting down (Cancelled).")
        loop.run_until_complete(_cleanup())
    except Exception as exc:
        log(f"Fatal error: {type(exc).__name__}: {exc}")
        loop.run_until_complete(_cleanup())
        sys.exit(1)
    finally:
        loop.close()
